// para que sobrevivan al siguiente turno (nueva ejecución del workflow)
const notasGuardar = JSON.stringify({
  horarios: mapeo,
  cita_id_real: $('Execute a SQL query11').first().json.cita_id
});

return [{ json: {
  mensaje: lista.trim(),
  notas_guardar: notasGuardar,   // ← esto va al campo "notas" en Update rows in a table15
  cita_id_temporal: $('Execute a SQL query11').first().json.id,   // la fila temporal (575)
  fecha: $('Webhook').first().json.body.mensaje.trim()
}}];

const fila = $input.first().json; // fila con notas = {"horarios":{...}, "cita_id_real":542}
const data = JSON.parse(fila.notas);
const mapeo = data.horarios;
const cita_id_real = data.cita_id_real;

const opcion = $('Webhook').first().json.body.mensaje.trim();
const hora = mapeo[opcion];

if (!hora) {
  return [{ json: { error: true, respuesta: "Opción inválida, elegí un número de la lista." }}];
}

const horaFin = `${String(parseInt(hora.split(':')[0]) + 1).padStart(2,'0')}:00`;
const fechaISO = fila.fecha.split('T')[0];

return [{ json: {
  cita_id_temporal: fila.id,
  cita_id_real: cita_id_real,
  fecha: fechaISO,
  hora: hora,
  hora_fin: horaFin,
  fecha_inicio_gcal: `${fechaISO}T${hora}:00-03:00`,
