UPDATE citas
SET fecha = '{{ $json.fecha }}',
    hora = '{{ $json.hora }}:00',
    estado = 'confirmado'
WHERE id = {{ $json.cita_id_real }}
RETURNING id, calendar_event_id, veterinario_id, mascota_id;

SELECT cl.nombre || ' ' || cl.apellido AS vet_nombre, m.nombre AS mascota_nombre
FROM clientes cl, mascotas m
WHERE cl.id = {{ $json.veterinario_id }}
AND m.id = {{ $json.mascota_id }}

